def evaluator(path=REF):
    from lerobot_training.eval_policy import PolicyEvaluator
    return PolicyEvaluator(str(path), device='cuda', num_action_samples=1,
        n_action_execute_steps=1, flow_integration_steps=4, controller_variant='feedback')

def _normalize_observation(
        self,
        state,
        oct_feature,
        velocity,
        previous_action,
    ):
        if velocity.dim() == 2:
            velocity = velocity[:, None, :].expand(
                -1,
                state.shape[1],
                -1,
            )
        if previous_action.dim() == 2:
            previous_action = previous_action[:, None, :].expand(
                -1,
                state.shape[1],
                -1,
            )
        return (
            (state - self.state_mean) / self.state_std,
            (oct_feature - self.oct_mean) / self.oct_std,
            (velocity - self.velocity_mean) / self.velocity_std,
            (
                previous_action - self.previous_action_mean
            ) / self.previous_action_std,
        )

def get_action(self, rgb, state, oct_feature):
        """
        从观测获取动作

        Args:
            rgb: [H, W, 3] numpy array
            state: [3] numpy array [A_deg, B_deg, C_mm]

        Returns:
            action: [3] numpy array [dA_deg, dB_deg, dC_mm]
        """
        if self.fine_evaluator is not None:
            oct_distance_mm = (
                float(np.linalg.norm(np.asarray(oct_feature[:3])))
                if bool(oct_feature[3] > 0.5)
                else float("inf")
            )
            if (
                not self.fine_active
                and oct_distance_mm <= self.fine_switch_error_mm
            ):
                self.fine_active = True
                self.invalidate_action_chunk()
            if (
                oct_distance_mm <= self.terminal_refine_error_mm
                and bool(oct_feature[3] > 0.5)
            ):
                from oct_terminal_refinement import (
                    solve_oct_terminal_action,
                )

                reference = self.fine_evaluator.reference
                if self.terminal_locked_solution is None:
                    estimate = solve_oct_terminal_action(
                        reference,
                        state,
                        oct_feature[:3],
                        self.fine_evaluator.camera_rotation,
                        neighbor_counts=2,
                    )
                    self.terminal_target_estimates.append(
                        np.asarray(
                            estimate["estimated_target_world_mm"],
                            dtype=np.float64,
                        )
                    )
                    if len(self.terminal_target_estimates) < (
                        self.terminal_confirm_frames
                    ):
                        self.control_mode_counts["stabilize"] += 1
                    else:
                        self.terminal_locked_target_world_mm = np.median(
                            np.stack(
                                self.terminal_target_estimates
                            ),
                            axis=0,
                        )
                        self.terminal_locked_solution = (
                            solve_oct_terminal_action(
                                reference,
                                state,
                                oct_feature[:3],
                                self.fine_evaluator.camera_rotation,
                                neighbor_counts=2,
                                target_world_override_mm=(
                                    self.terminal_locked_target_world_mm
                                ),
                            )
                        )
                if self.terminal_locked_solution is not None:
                    self.terminal_refinement_active = True
                    self.control_mode_counts["terminal"] += 1
                    current_task = (
                        np.asarray(state, dtype=np.float64)
                        / np.array(
                            [180.0 / np.pi, 180.0 / np.pi, 1000.0]
                        )
                    )
                    target_task = (
                        self.fine_evaluator.reference.task_from_encoders(
                            self.terminal_locked_solution[
                                "encoder_counts"
                            ],
                            reference_task=current_task,
                        )
                    )
                    target_abc = target_task * np.array(
                        [180.0 / np.pi, 180.0 / np.pi, 1000.0]
                    )
                    self.last_terminal_solution = (
                        self.terminal_locked_solution
                    )
                    return target_abc - np.asarray(
                        state,
                        dtype=np.float64,
                    )
            if self.fine_active:
                self.control_mode_counts["fine"] += 1
                return self.fine_evaluator.get_action(
                    rgb,
                    state,
                    oct_feature,
                )
            self.control_mode_counts["coarse"] += 1

        # 预处理
        img_tensor = (
            None
            if self.is_regression or self.is_guided_regression
            else self.preprocess_image(rgb)
        )
        state_tensor = torch.from_numpy(state).float()

        # 添加到缓冲
        self.obs_buffer.append({
            'image': img_tensor,
            'state': state_tensor,
            'oct': torch.from_numpy(oct_feature).float(),
        })

        # 如果缓冲不足，返回零动作
        if len(self.obs_buffer) < self.n_obs_steps:
            return np.zeros(3, dtype=np.float32)

        # 保持固定长度
        if len(self.obs_buffer) > self.n_obs_steps:
            self.obs_buffer.pop(0)

        if self.action_queue:
            return np.asarray(self.action_queue.pop(0), dtype=np.float64)

        # 准备输入
        obs_states = torch.stack([obs['state'] for obs in self.obs_buffer])  # [T, 3]
        obs_oct = torch.stack([obs['oct'] for obs in self.obs_buffer])
        obs_states = obs_states.unsqueeze(0).to(self.device)  # [1, T, 3]
        obs_oct = obs_oct.unsqueeze(0).to(self.device)
        velocity = None
        if self.include_velocity:
            velocity = (
                obs_states[:, -1] - obs_states[:, -2]
            ) / 0.05
        previous_action = None
        if self.include_previous_action:
            previous_action = torch.from_numpy(
                self.previous_action.astype(np.float32)
            ).unsqueeze(0).to(self.device)
        if self.is_regression:
            state_array = np.asarray(state, dtype=np.float64)
            if self.regression_previous_state is None:
                velocity = np.zeros(3, dtype=np.float32)
            else:
                velocity = (
                    (state_array - self.regression_previous_state) / 0.05
                ).astype(np.float32)
            with torch.no_grad():
                action = self.model(
                    obs_states[:, -1],
                    obs_oct[:, -1],
                    velocity=torch.from_numpy(velocity).unsqueeze(0).to(self.device),
                    previous_action=torch.from_numpy(
                        self.regression_previous_action.copy()
                    ).unsqueeze(0).to(self.device),
                )[0].cpu().numpy()
            self.regression_previous_state = state_array.copy()
            return action
        if self.is_guided_regression:
            base = proportional_guided_action(
                self.reference,
                np.asarray(state, dtype=np.float64),
                np.asarray(oct_feature[:3], dtype=np.float64),
                self.camera_rotation,
                valid=bool(oct_feature[3] > 0.5),
                gain=float(self.checkpoint['config']['gain']),
                saturation=np.asarray(
                    self.checkpoint['config']['base_saturation'],
                    dtype=np.float64,
                ),
                relative_damping=float(
                    self.checkpoint['config'].get(
                        'relative_damping',
                        1e-3,
                    )
                ),
            )
            with torch.no_grad():
                action = self.model(
                    obs_states[:, -1],
                    obs_oct[:, -1],
                    torch.from_numpy(base.astype(np.float32))
                    .unsqueeze(0)
                    .to(self.device),
                )[0][0].cpu().numpy()
            return action

        obs_images = torch.stack([obs['image'] for obs in self.obs_buffer])
        obs_images = obs_images.unsqueeze(0).to(self.device)  # [1, T, 3, 224, 224]
        if self.is_flow_temporal_unet or self.is_dit_rectified_flow:
            sample_count = self.num_action_samples
            timing_cuda = self.measure_inference and self.device.type == "cuda"
            if timing_cuda:
                timing_start = torch.cuda.Event(enable_timing=True)
                timing_end = torch.cuda.Event(enable_timing=True)
                timing_start.record(torch.cuda.current_stream(self.device))
            inference_started = perf_counter() if self.measure_inference else None
            try:
                with torch.no_grad():
                    chunks = self.model.sample(
                        obs_images.expand(
                            sample_count, *obs_images.shape[1:]
                        ),
                        obs_states.expand(
                            sample_count, *obs_states.shape[1:]
                        ),
                        obs_oct.expand(
                            sample_count, *obs_oct.shape[1:]
                        ),
                        velocity.expand(
                            sample_count, *velocity.shape[1:]
                        ),
                        previous_action.expand(
                            sample_count, *previous_action.shape[1:]
                        ),
                        steps=self.flow_integration_steps,
                        generator=self.action_generator,
                    )
            except torch.cuda.OutOfMemoryError:
                if self.measure_inference:
                    raise  # A fallback would change both latency and the RNG stream.
                torch.cuda.empty_cache()
                sampled_chunks = []
                with torch.no_grad():
                    for _ in range(sample_count):
                        sampled_chunks.append(
                            self.model.sample(
                                obs_images,
                                obs_states,
                                obs_oct,
                                velocity,
                                previous_action,
                                steps=self.flow_integration_steps,
                                generator=self.action_generator,
                            )[0]
                        )
                chunks = torch.stack(sampled_chunks, dim=0)
            if sample_count > 1:
                aggregated = (
                    chunks.mean(dim=0)
                    if self.action_aggregation == "mean"
                    else chunks.median(dim=0).values
                )
            else:
                aggregated = chunks[0]
            if timing_cuda:
                timing_end.record(torch.cuda.current_stream(self.device))
                timing_end.synchronize()
                self.last_policy_inference_ms = timing_start.elapsed_time(timing_end)
            elif inference_started is not None:
                self.last_policy_inference_ms = (
                    perf_counter() - inference_started
                ) * 1000.0
            if self.measure_inference and not bool(torch.isfinite(chunks).all()):
                raise FloatingPointError("nonfinite policy sample before aggregation")
            action_chunk = aggregated.cpu().numpy()
            if self.n_action_execute_steps > 1:
                self.action_queue = action_chunk[
                    1:self.n_action_execute_steps
                ].copy().tolist()
            return action_chunk[0]

        guided_base = None
        if self.guided_oct:
            guided_base_array = proportional_guided_action(
                self.reference,
                np.asarray(state, dtype=np.float64),
                np.asarray(oct_feature[:3], dtype=np.float64),
                self.camera_rotation,
                valid=bool(oct_feature[3] > 0.5),
                gain=float(self.checkpoint['config']['guided_gain']),
                saturation=np.asarray(
                    self.checkpoint['config']['guided_saturation'],
                    dtype=np.float64,
                ),
                relative_damping=float(
                    self.checkpoint['config'].get(
                        'guided_relative_damping',
                        1e-3,
                    )
                ),
            )
            guided_base = torch.from_numpy(
                guided_base_array.astype(np.float32)
            ).unsqueeze(0).to(self.device)

        # 推理。逐次采样后取中位数，避免单个低质量扩散采样直接推动闭环。
        # 顺序采样而非常量 batch repeat，避免多路并行评估时增加峰值显存。
        sample_count = self.num_action_samples
        chunks = None
        if self.parallel_action_samples and sample_count > 1:
            try:
                with torch.no_grad():
                    chunks = self.model(
                        obs_images.expand(
                            sample_count, *obs_images.shape[1:]
                        ),
                        obs_states.expand(
                            sample_count, *obs_states.shape[1:]
                        ),
                        obs_oct=(
                            obs_oct.expand(
                                sample_count, *obs_oct.shape[1:]
                            )
                            if obs_oct is not None else None
                        ),
                        generator=self.action_generator,
                        guided_base=(
                            guided_base.expand(
                                sample_count, *guided_base.shape[1:]
                            )
                            if guided_base is not None else None
                        ),
                        velocity=(
                            velocity.expand(
                                sample_count, *velocity.shape[1:]
                            )
                            if velocity is not None else None
                        ),
                        previous_action=(
                            previous_action.expand(
                                sample_count,
                                *previous_action.shape[1:],
                            )
                            if previous_action is not None else None
                        ),
                    )
            except torch.cuda.OutOfMemoryError:
                torch.cuda.empty_cache()
                chunks = None
        if chunks is None:
            with torch.no_grad():
                sampled_chunks = []
                for _ in range(sample_count):
                    actions = self.model(
                        obs_images,
                        obs_states,
                        obs_oct=obs_oct if self.use_oct else None,
                        generator=self.action_generator,
                        guided_base=guided_base,
                        velocity=velocity,
                        previous_action=previous_action,
                    )  # [1, n_action_steps, 3]
                    sampled_chunks.append(actions[0])
            chunks = torch.stack(sampled_chunks, dim=0)
        if sample_count > 1:
            action_chunk = (
                chunks.mean(dim=0)
                if self.action_aggregation == "mean"
                else chunks.median(dim=0).values
            ).cpu().numpy()
        else:
            action_chunk = chunks[0].cpu().numpy()

        if self.n_action_execute_steps > 1:
            self.action_queue = action_chunk[
                1:self.n_action_execute_steps
            ].copy().tolist()
        return action_chunk[0]
